gameActivityImportAdditions.insert:
import android.os.Build;
import android.os.VibrationEffect;
import android.os.Vibrator;
import android.os.VibratorManager;

gameActivityClassAdditions.insert:
public void AndroidThunkJava_MiniGameVibrate(final int intensity, final int durationMs)
{
	if (durationMs < 1)
	{
		return;
	}
	runOnUiThread(new Runnable()
	{
		@Override
		public void run()
		{
			try
			{
				Vibrator vibrator = null;
				if (Build.VERSION.SDK_INT >= 31)
				{
					VibratorManager manager = (VibratorManager)getSystemService(VIBRATOR_MANAGER_SERVICE);
					if (manager != null)
					{
						vibrator = manager.getDefaultVibrator();
					}
				}
				else
				{
					vibrator = (Vibrator)getSystemService(VIBRATOR_SERVICE);
				}
				if (vibrator == null || !vibrator.hasVibrator())
				{
					return;
				}
				final int amplitude = Math.max(1, Math.min(255, intensity));
				if (Build.VERSION.SDK_INT >= 26)
				{
					vibrator.vibrate(VibrationEffect.createOneShot((long)durationMs, amplitude));
				}
				else
				{
					vibrator.vibrate((long)durationMs);
				}
			}
			catch (Exception ignored)
			{
			}
		}
	});
}

